div.textarea:
const k = x / P.C4 - P.C125;
const e = y / P.C9 + P.C6;
const o = Math.sqrt(k*k + e*e) / P.C9;
if (o < 1e-6) return null;

const ty = Math.tan(y / 2);
if (!isFinite(ty)) return null;

const q = 3 * (ty / 2 + Math.cos(y)) / k 
        + k * (P.C5 / o + o * Math.sin(y) * Math.sin(e + o * 4 - t));

const c = o / 2 + e / 2 - t / 4;
const px = q + 40 * Math.cos(c) + 200;
const py = q * Math.sin(c) - k * k * o / P.C6 + e * o * 12;

return [px, py];

svg.script:
(function () {
  "use strict";

  /* ── DOM References ─────────────────────────────────── */
  const svg = document.documentElement;
  const fossilGroup = document.getElementById("fossil");
  const baseTransform = document.getElementById("fossil-base-transform");
  const viewport = document.getElementById("fossil-viewport");
  const statusText = document.getElementById("status-text");
  const seedDisplay = document.getElementById("seed-display");
  const algoDisplay = document.getElementById("algo-display");
  const slicesDisplay = document.getElementById("slices-display");
  const genTimeText = document.getElementById("gen-time");

  /* ── UI Elements ────────────────────────────────────── */
  const ui = {
    algSelect: document.getElementById("algSelect"),
    customBlock: document.getElementById("customBlock"),
    algCustom: document.getElementById("algCustom"),
    btnApplyCustom: document.getElementById("btnApplyCustom"),
    seed: document.getElementById("inSeed"),
    slices: document.getElementById("inSlices"),
    nx: document.getElementById("inNX"),
    ny: document.getElementById("inNY"),
    c4: document.getElementById("inC4"),
    c5: document.getElementById("inC5"),
    c125: document.getElementById("inC125"),
    c9: document.getElementById("inC9"),
    c6: document.getElementById("inC6"),
    btnRandom: document.getElementById("btnRandom"),
    btnZoomIn: document.getElementById("btnZoomIn"),
    btnZoomOut: document.getElementById("btnZoomOut"),
    btnReset: document.getElementById("btnResetView"),
    lblSeed: document.getElementById("lblSeed"),
    lblSlices: document.getElementById("lblSlices"),
    lblNX: document.getElementById("lblNX"),
    lblNY: document.getElementById("lblNY"),
    lblC4: document.getElementById("lblC4"),
    lblC5: document.getElementById("lblC5"),
    lblC125: document.getElementById("lblC125"),
    lblC9: document.getElementById("lblC9"),
    lblC6: document.getElementById("lblC6")
  };

  /* ── Application State ──────────────────────────────── */
  let state = {
    alg: "Exact Source",
    customCode: ui.algCustom.value,
    seed: 42,
    slices: 6,
    NX: 100, NY: 90,
    C4: 4.0, C5: 5.0, C125: 12.5, C9: 9.0, C6: 6.0,
    viewX: 0, viewY: 0, viewScale: 1
  };

  /* ── PRNG (mulberry32) ──────────────────────────────── */
  function mulberry32(a) {
    return function() {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  /* ── Global Algorithm Library ──────────────────────── */
  const algorithms = {
    "Exact Source": function(x, y, t, P) {
      const k = x / P.C4 - P.C125;
      const e = y / P.C9 + P.C6;
      const o = Math.sqrt(k*k + e*e) / P.C9;
      if (o < 1e-6 || !isFinite(o)) return null;
      if (Math.abs(k) < 1e-4) return null;

      const ty = Math.tan(y / 2);
      if (!isFinite(ty) || Math.abs(ty) > 1e4) return null;

      const cy = Math.cos(y), sy = Math.sin(y);
      const inner = e + o * 4 - t;
      let q = 3 * (ty / 2 + cy) / k + k * (P.C5 / o + o * sy * Math.sin(inner));
      if (!isFinite(q) || Math.abs(q) > 5e3) return null;

      const c = o / 2 + e / 2 - t / 4;
      let px = q + 40 * Math.cos(c) + 200;
      let py = q * Math.sin(c) - k * k * o / P.C6 + e * o * 12;

      return [px, py];
    },

    "Ammonite Spiral": function(x, y, t, P) {
      const k = x / P.C4 - P.C125;
      const e = y / P.C9 + P.C6;
      const o = Math.sqrt(k*k + e*e) + 0.1;
      const ang = Math.atan2(e, k) + o / P.C5 + t;
      const r = o * P.C9;

      let px = r * Math.cos(ang) * 2 + 200;
      let py = r * Math.sin(ang) * 2 - 300;

      if (!isFinite(px) || !isFinite(py)) return null;
      return [px, py];
    },

    "Ribbon Pterodactyl": function(x, y, t, P) {
      const k = x / P.C4 - P.C125;
      const e = y / P.C9 + P.C6;
      const o = Math.sqrt(k*k + e*e) / P.C9 + 0.1;

      let px = k * P.C5 + Math.sin(e * P.C9 + t) * 50 / o;
      let py = e * P.C5 * P.C6 + Math.cos(k * P.C9 + t) * 50 / o;

      if (!isFinite(px) || !isFinite(py) || Math.abs(px) > 5e3 || Math.abs(py) > 5e3) return null;
      return [px, py];
    },

    "Crinoid Feather": function(x, y, t, P) {
      const k = x / P.C4 - P.C125;
      const e = y / P.C9 + P.C6;
      const o = Math.abs(k) + 0.1;
      const ang = e / P.C5 + t;

      let px = o * Math.sin(ang) * P.C9 + 200;
      let py = e * P.C6 - o * Math.cos(ang) * P.C9;

      return [px, py];
    },

    "Anomalocaris": function(x, y, t, P) {
      const k = x / P.C4 - P.C125;
      const e = y / P.C9 + P.C6;
      const o = Math.sin(k * 0.5) * Math.cos(e * 0.5);

      let px = k * P.C5 + o * P.C125 + Math.sin(t) * 20;
      let py = e * P.C6 + o * P.C9;

      return [px, py];
    }
  };

  /* ── Render Pipeline ────────────────────────────────── */
  let debounceTimer;
  function scheduleRender() {
    statusText.textContent = "CALCULATING MATRIX...";
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(renderFossil, 50);
  }

  function renderFossil() {
    const startTime = performance.now();
    const P = { C4: state.C4, C5: state.C5, C125: state.C125, C9: state.C9, C6: state.C6 };
    const tStep = Math.PI / 8;
    const ns = "http://www.w3.org/2000/svg";

    fossilGroup.innerHTML = "";

    // Resolve the target algorithm function
    let algoFn;
    if (state.alg === "Custom") {
      try {
        algoFn = new Function('x', 'y', 't', 'P', state.customCode);
        algoDisplay.textContent = "Custom";
      } catch (err) {
        statusText.textContent = "ERROR: INVALID CUSTOM SYNTAX";
        return;
      }
    } else {
      algoFn = algorithms[state.alg];
      algoDisplay.textContent = state.alg;
    }

    if (!algoFn) {
      statusText.textContent = "ERROR: ALGORITHM NOT FOUND";
      return;
    }

    let minX=Infinity, minY=Infinity, maxX=-Infinity, maxY=-Infinity;
    const slices = [];

    // Generate Point Clouds
    for (let s = 0; s < state.slices; s++) {
      const t = s * tStep;
      const pts = [];
      for (let yi = 0; yi < state.NY; yi++) {
        for (let xi = 0; xi < state.NX; xi++) {
          const x = xi + 0.5;
          const y = yi + 0.5;

          let p = null;
          try {
            p = algoFn(x, y, t, P);
          } catch (e) {
            p = null; // Fail silently per-point for malformed custom code
          }

          if (p && isFinite(p[0]) && isFinite(p[1])) {
            pts.push(p);
            if (p[0] < minX) minX = p[0];
            if (p[0] > maxX) maxX = p[0];
            if (p[1] < minY) minY = p[1];
            if (p[1] > maxY) maxY = p[1];
          }
        }
      }
      slices.push(pts);
    }

    if (minX === Infinity) { 
      statusText.textContent = "ERROR: NULL BOUNDING BOX (Check Custom Code)";
      return; 
    }

    // Fit to Plate Viewport (1560x1000 starting at 40,40)
    const padX = 100, padY = 100;
    const vw = 1560 - padX * 2;
    const vh = 1000 - padY * 2;
    const sx = vw / (maxX - minX);
    const sy = vh / (maxY - minY);
    const scale = Math.min(sx, sy);
    const tx = 40 + padX + (vw - (maxX - minX) * scale) / 2 - minX * scale;
    const ty = 40 + padY + (vh - (maxY - minY) * scale) / 2 - minY * scale;

    baseTransform.setAttribute("transform", `translate(${tx}, ${ty}) scale(${scale})`);

    // 1-Bit Vectorization (Zero-length subpaths)
    for (let s = 0; s < slices.length; s++) {
      let d = "";
      for (const p of slices[s]) {
        d += `M${p[0].toFixed(1)},${p[1].toFixed(1)}h0`;
      }

      const path = document.createElementNS(ns, "path");
      path.setAttribute("d", d);
      path.setAttribute("stroke", "#000");
      path.setAttribute("fill", "none");
      path.setAttribute("stroke-linecap", "round");
      path.setAttribute("shape-rendering", "crispEdges");
      path.setAttribute("vector-effect", "non-scaling-stroke"); 

      // Depth mapping via stroke width
      const depth = (s + 1) / slices.length;
      path.setAttribute("stroke-width", (0.8 + depth * 1.5).toFixed(2));
      fossilGroup.appendChild(path);
    }

    const endTime = performance.now();
    statusText.textContent = `READY · ID ${state.seed} · GEN TIME ${Math.round(endTime - startTime)}ms`;
    genTimeText.textContent = `GEN TIME: ${Math.round(endTime - startTime)}ms`;
  }

  /* ── Randomizer Logic ──────────────────────────────── */
  function randomize() {
    const rng = mulberry32(Date.now() % 2147483647);

    state.seed = Math.floor(rng() * 99999) + 1;
    state.C4 = 2 + rng() * 6;
    state.C5 = 1 + rng() * 9;
    state.C125 = 6 + rng() * 12;
    state.C9 = 4 + rng() * 10;
    state.C6 = 3 + rng() * 6;
    state.slices = 4 + Math.floor(rng() * 8);
    state.NX = 80 + Math.floor(rng() * 120);
    state.NY = 80 + Math.floor(rng() * 120);

    // Occasionally switch algorithm randomly
    const algKeys = Object.keys(algorithms);
    state.alg = algKeys[Math.floor(rng() * algKeys.length)];
    ui.algSelect.value = state.alg;
    ui.customBlock.style.display = 'none';

    syncUIToState();
    scheduleRender();
  }

  function syncUIToState() {
    ui.seed.value = state.seed;
    ui.slices.value = state.slices;
    ui.nx.value = state.NX;
    ui.ny.value = state.NY;
    ui.c4.value = state.C4;
    ui.c5.value = state.C5;
    ui.c125.value = state.C125;
    ui.c9.value = state.C9;
    ui.c6.value = state.C6;
    updateLabels();
  }

  function updateLabels() {
    ui.lblSeed.textContent = state.seed;
    ui.lblSlices.textContent = state.slices;
    ui.lblNX.textContent = state.NX;
    ui.lblNY.textContent = state.NY;
    ui.lblC4.textContent = state.C4.toFixed(2);
    ui.lblC5.textContent = state.C5.toFixed(2);
    ui.lblC125.textContent = state.C125.toFixed(2);
    ui.lblC9.textContent = state.C9.toFixed(2);
    ui.lblC6.textContent = state.C6.toFixed(2);

    seedDisplay.textContent = state.seed;
    slicesDisplay.textContent = state.slices;
  }

  /* ── Viewport Transforms (Pan & Zoom) ──────────────── */
  function updateTransform() {
    viewport.setAttribute("transform", `translate(${state.viewX}, ${state.viewY}) scale(${state.viewScale})`);
  }

  function getMousePosition(evt) {
    const pt = svg.createSVGPoint();
    pt.x = evt.clientX; pt.y = evt.clientY;
    return pt.matrixTransform(svg.getScreenCTM().inverse());
  }

  svg.addEventListener('wheel', (e) => {
    if (e.target.closest('foreignObject')) return;
    e.preventDefault();

    const pt = getMousePosition(e);
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    const oldScale = state.viewScale;
    const newScale = Math.max(0.2, Math.min(50, oldScale * delta));

    state.viewX = pt.x - (pt.x - state.viewX) * (newScale / oldScale);
    state.viewY = pt.y - (pt.y - state.viewY) * (newScale / oldScale);
    state.viewScale = newScale;

    updateTransform();
  });

  ui.btnZoomIn.addEventListener('click', () => {
    state.viewScale *= 1.2;
    updateTransform();
  });
  ui.btnZoomOut.addEventListener('click', () => {
    state.viewScale = Math.max(0.2, state.viewScale / 1.2);
    updateTransform();
  });
  ui.btnReset.addEventListener('click', () => {
    state.viewX = 0; state.viewY = 0; state.viewScale = 1;
    updateTransform();
  });

  /* ── Pan Logic ─────────────────────────────────────── */
  let isPanning = false;
  let startPanX, startPanY, startViewX, startViewY;

  svg.addEventListener('mousedown', (e) => {
    if (e.target.closest('foreignObject')) return;
    isPanning = true;
    startPanX = e.clientX; startPanY = e.clientY;
    startViewX = state.viewX; startViewY = state.viewY;
    svg.style.cursor = "grabbing";
  });

  window.addEventListener('mousemove', (e) => {
    if (!isPanning) return;
    const ctm = svg.getScreenCTM();
    const scale = ctm.a; 

    state.viewX = startViewX + (e.clientX - startPanX) / scale;
    state.viewY = startViewY + (e.clientY - startPanY) / scale;
    updateTransform();
  });

  window.addEventListener('mouseup', () => {
    isPanning = false;
    svg.style.cursor = "default";
  });

  /* ── UI Event Bindings ─────────────────────────────── */
  ui.algSelect.addEventListener('change', (e) => {
    state.alg = e.target.value;
    if (state.alg === "Custom") {
      ui.customBlock.style.display = 'block';
    } else {
      ui.customBlock.style.display = 'none';
      scheduleRender();
    }
  });

  ui.btnApplyCustom.addEventListener('click', () => {
    state.customCode = ui.algCustom.value;
    scheduleRender();
  });

  ui.seed.addEventListener('input', (e) => { state.seed = parseInt(e.target.value) || 1; updateLabels(); scheduleRender(); });
  ui.slices.addEventListener('input', (e) => { state.slices = parseInt(e.target.value); updateLabels(); scheduleRender(); });
  ui.nx.addEventListener('input', (e) => { state.NX = parseInt(e.target.value); updateLabels(); scheduleRender(); });
  ui.ny.addEventListener('input', (e) => { state.NY = parseInt(e.target.value); updateLabels(); scheduleRender(); });
  ui.c4.addEventListener('input', (e) => { state.C4 = parseFloat(e.target.value); updateLabels(); scheduleRender(); });
  ui.c5.addEventListener('input', (e) => { state.C5 = parseFloat(e.target.value); updateLabels(); scheduleRender(); });
  ui.c125.addEventListener('input', (e) => { state.C125 = parseFloat(e.target.value); updateLabels(); scheduleRender(); });
  ui.c9.addEventListener('input', (e) => { state.C9 = parseFloat(e.target.value); updateLabels(); scheduleRender(); });
  ui.c6.addEventListener('input', (e) => { state.C6 = parseFloat(e.target.value); updateLabels(); scheduleRender(); });

  ui.btnRandom.addEventListener('click', randomize);

  // Initial Render
  syncUIToState();
  scheduleRender();

})();
